-- PostgreSQL, sockets database. Apply before deploying the events module.
-- synchronize is disabled in this project. This script does not run at startup.
BEGIN;

CREATE TABLE IF NOT EXISTS "EVEEVENTO" (
  "OID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TITULO" varchar(160) NOT NULL,
  "DESCRIPCION" text NOT NULL,
  "LUGAR" varchar(250) NOT NULL,
  "FECINICIO" timestamp without time zone NOT NULL,
  "FECFIN" timestamp without time zone NOT NULL,
  "ORGANIDESCRI" varchar(200) NOT NULL,
  "ORGANIOID" integer NOT NULL,
  "ADNCENATE" smallint NOT NULL,
  "FECCRE" timestamp without time zone NOT NULL,
  "FECACT" timestamp without time zone NOT NULL,
  CONSTRAINT "CK_EVEEVENTO_RANGO_FECHAS" CHECK ("FECFIN" > "FECINICIO")
);

CREATE INDEX IF NOT EXISTS "IX_EVEEVENTO_ORGANIZADOR_INICIO"
  ON "EVEEVENTO" ("ORGANIOID", "FECINICIO");

CREATE INDEX IF NOT EXISTS "IX_EVEEVENTO_RANGO_FECHAS"
  ON "EVEEVENTO" ("FECINICIO", "FECFIN");

CREATE TABLE IF NOT EXISTS "EVEINVITACION" (
  "OID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "EVEEVENTO" integer NOT NULL,
  "USUINVITOID" integer NOT NULL,
  "ADNCENATE" smallint NOT NULL,
  "TIPOUSUINV" smallint NOT NULL,
  "ESTADOCODE" smallint NOT NULL DEFAULT 1,
  "FECINV" timestamp without time zone NOT NULL,
  "FECRESP" timestamp without time zone,
  CONSTRAINT "FK_EVEINVITACION_EVEEVENTO"
    FOREIGN KEY ("EVEEVENTO") REFERENCES "EVEEVENTO" ("OID") ON DELETE CASCADE,
  CONSTRAINT "CK_EVEINVITACION_ESTADOCODE" CHECK ("ESTADOCODE" IN (1, 2, 3))
);

CREATE UNIQUE INDEX IF NOT EXISTS "UQ_EVEINVITACION_EVENTO_USUARIO"
  ON "EVEINVITACION" ("EVEEVENTO", "USUINVITOID", "ADNCENATE", "TIPOUSUINV");

CREATE INDEX IF NOT EXISTS "IX_EVEINVITACION_USUARIO_ESTADOCODE"
  ON "EVEINVITACION" ("USUINVITOID", "ADNCENATE", "TIPOUSUINV", "ESTADOCODE");

COMMIT;
